n=18
out=[[1]*n for _ in range(n)]
# Top half of the 7-shape translated maximally to the upper-left corner.
top={ (5,7),(5,8), (6,6),(6,7),(6,8),(6,9), (7,6),(7,7),(7,9),(7,10), (8,7),(8,9),(8,10) }
# Bottom half translated maximally to the lower-left corner.
bottom={ (10,6),(10,7),(10,8), (11,7), (12,6),(12,7),(12,8),(12,9),(12,10) }
for r,c in top:
    out[r-5][c-6]=7
for r,c in bottom:
    out[r+5][c-6]=7
# Cells on the cut row stay in place; the 2 ray reaches the shape's row extent.
for c in range(8):
    out[9][c]=2
out[9][6]=7; out[9][7]=7
print('\n'.join(' '.join(map(str,row)) for row in out))
print([len(row) for row in out])
